-- Refines the DBS and MDM FAQs already seeded from the reference material in V4.
-- Keeps FAQ IDs, keywords, and usage history; no FAQ rows are added or deleted.

UPDATE faqs
SET topic = '시스템·관리',
    title = CASE id
        WHEN 123 THEN '[DBS] 디벗관리시스템의 용도와 조회 메뉴'
        WHEN 124 THEN '[DBS] 디벗관리시스템과 MDM·CEU의 연동 여부'
        WHEN 125 THEN '[DBS] 계정 ID 또는 비밀번호 분실 시 조치'
        WHEN 126 THEN '[DBS] 신규 기기 등록 및 보급 절차'
        WHEN 127 THEN '[DBS] 보급받지 않은 기기가 디벗관리 메뉴에 표시되는 경우'
        WHEN 128 THEN '[DBS] 시스템 수량과 학교 보유 수량이 다른 경우'
        WHEN 129 THEN '[DBS] 시스템 정보 수정 요청 방법'
        WHEN 130 THEN '[DBS] 명렬표·기기정보 수정 방법'
        WHEN 131 THEN '[DBS] 학생·기기 일련번호 매칭 명렬표 요청'
        WHEN 132 THEN '[DBS] 학생 변경 후 A/S 이력 표시 기준'
        WHEN 133 THEN '[DBS] 2026년 방문 점검표 내려받기'
        WHEN 134 THEN '[MDM] OS별 기기 관리 시스템'
        WHEN 135 THEN '[MDM] 신규 보급·재구매 기기의 관리 설정 상태'
        WHEN 136 THEN '[MDM] 공장 초기화 후 관리 시스템 재설치 여부'
        WHEN 137 THEN '[MDM] 기기 잠금 비밀번호 분실 시 초기화 가능 여부'
        WHEN 138 THEN '[MDM] 초기화 명령이 대기 중이고 연결 상태가 갱신되지 않는 경우'
        WHEN 139 THEN '[MDM] Argos MDM과 Argos AMA의 차이'
        WHEN 140 THEN '[MDM] 관리 시스템이 설치되지 않은 기기 조치'
        WHEN 141 THEN '[MDM] 기술지원 문의처'
        WHEN 142 THEN '[MDM] 기술지원센터에서 고객지원센터로 문의를 안내한 경우'
        WHEN 143 THEN '[MDM] 단말 현황에 Wi-Fi 아이콘이 표시되지 않는 경우'
        WHEN 144 THEN '[MDM] 단말 현황의 FCM 토큰 만료 상태 조치'
        WHEN 145 THEN '[MDM] 단말 상세 코드로 기기 잠금 비밀번호 확인 가능 여부'
        WHEN 146 THEN '[MDM] 앱 배포 방식과 지원 스토어'
        WHEN 147 THEN '[MDM] 앱 배포 방법 문의처'
        WHEN 148 THEN '[MDM] AMA 앱 배포 방법 문의처'
        WHEN 149 THEN '[MDM] 분실 기기의 위치 확인 지원 범위'
        WHEN 150 THEN '[MDM] 분실 등록 후 기기 위치 확인 방법'
        WHEN 151 THEN '[MDM] 분실 등록 명령이 적용되지 않는 경우'
        WHEN 152 THEN '[MDM] 분실 등록 기기의 잠금 해제 방법'
        WHEN 153 THEN '[MDM] “IT 관리자에게 문의하세요” 표시 조치'
        WHEN 154 THEN '[MDM] 전입·전출에 따른 학생 정보 변경'
        WHEN 155 THEN '[MDM] AMA 등록용 QR 코드 조회 및 사용'
        WHEN 156 THEN '[MDM] 비밀번호 초기화 명령 후 키오스크 모드가 적용된 경우'
        ELSE title
    END,
    content = CASE id
        WHEN 123 THEN '디벗관리시스템(DBS)은 서울특별시교육청이 운영을 주관하고 케이원이 개발한 별도 시스템입니다. 교육청과 유지보수 업체가 기기 보급·관리 및 서비스 현황을 확인하는 데 사용합니다.\n\n- [디벗관리]: 최초 보급 기준 기기와 예비기기 목록\n- [명렬표관리]: 학생 학적정보와 기기 일련번호가 연결된 목록\n- 계정 권한에 따라 A/S 관리, 미정산, 게시판 등 메뉴 조회\n\n최초 보급 자료와 현재 학교의 보유·배부 현황이 다를 수 있습니다. 특히 2022년 도입 기기는 학교의 실제 관리 현황과 대조해 정보 갱신이 필요한지 확인합니다.'
        WHEN 124 THEN '디벗관리시스템은 MDM·CEU와 별도로 운영되는 자산·서비스 현황 관리 시스템입니다. 기기 제어 명령이나 관리 정책을 MDM·CEU와 직접 동기화하는 시스템은 아닙니다. 학교 필수 관리 여부는 교육청 지침을 따르며, 자료상 학교 활용은 권고 사항입니다.'
        WHEN 125 THEN 'ID를 잊은 경우 DBS의 계정 관리 메뉴에서 학교를 검색해 계정 정보를 확인하거나 시스템 안내에 따라 관리자에게 문의합니다. 비밀번호를 잊은 경우 임의의 공통 비밀번호를 사용하지 말고 공식 계정 복구·초기화 절차를 요청합니다. 계정 복구 후에는 본인 비밀번호를 변경합니다.'
        WHEN 126 THEN '신규 기기 보급 시 일반적인 등록 흐름:\n1. 교육청과 유지보수 업체가 학교에 보급 안내를 전달합니다.\n2. 학교가 안내에 따라 명렬표 학적정보와 학교 Wi-Fi 정보를 준비합니다.\n3. 유지보수 업체가 시스템 계정과 기기 등록을 준비합니다.\n4. 기기 보급 시 학교 Wi-Fi 설정을 진행합니다.\n5. 보급 직후 기기의 초기 불량과 기본 동작을 확인합니다.\n\n이 절차는 신규 보급 기준이며, 학교·사업별 안내가 있으면 해당 안내를 우선합니다.'
        WHEN 127 THEN '표시된 기기의 일련번호와 학교의 보급·인수 자료를 대조합니다. 해당 학교에 보급되지 않은 기기로 확인되면 학교명, 보급 연도, 일련번호를 정리해 DBS 운영 담당 경로로 정정 요청합니다. 확인 전에는 목록에서 임의로 삭제하지 않습니다.'
        WHEN 128 THEN '최초 보급 목록, 명렬표 매칭 목록, 현재 학교의 실제 보유 수량은 기준 시점과 관리 목적이 달라 서로 다를 수 있습니다. 학교명, 보급 연도, 차이가 확인된 일련번호와 수량을 정리해 DBS 운영 담당 경로로 확인·갱신을 요청합니다.'
        WHEN 129 THEN 'DBS 초기 화면에 표시되는 정보 수정 안내와 대표 이메일을 확인해 수정 자료를 전달합니다. 자료상 공용 문의 주소는 kone_sen@k-one.co.kr입니다. 최신 연락처가 사이트에 별도로 표시되면 사이트의 최신 안내를 우선합니다.'
        WHEN 130 THEN '명렬표·기기정보 수정 기능이 제공되는 경우 학교 담당자가 시스템에서 직접 수정합니다. 메뉴에 수정 기능이 없거나 권한이 제한되어 있으면 DBS 화면의 최신 안내에 표시된 연락 경로로 수정 자료를 요청합니다. 과거 개발 일정은 현재 기능 제공 여부를 보장하지 않으므로 실제 화면을 기준으로 확인합니다.'
        WHEN 131 THEN '학생과 기기 일련번호가 연결된 자료가 필요하면 학교명과 필요한 보급 연도를 확인해 DBS 운영 담당 경로로 요청합니다. 최초 보급 시점의 자료는 이후 학교에서 변경한 정보와 다를 수 있으므로, 최신 매칭 현황은 DBS의 [명렬표관리]에서 내려받은 자료와 대조합니다. 학생 이름·연락처 등 개인정보는 요청 목적에 필요한 범위로만 전달합니다.'
        WHEN 132 THEN '학생과 기기의 매칭을 변경한 뒤 A/S 이력을 조회하면 변경 후 현재 매칭된 학생 기준으로 표시될 수 있습니다. 과거 이력의 표시 기준은 자료상 현재 시스템 동작에 따른 것이며, 기존 요청자 기준의 이력 보존 여부가 필요한 경우 DBS 운영 담당자에게 확인합니다.'
        WHEN 133 THEN '2026년 방문 점검 상세 점검표는 DBS의 [점검확인서] 메뉴에서 내려받습니다. 상세 점검표 메뉴 자체에는 엑셀 내려받기 기능이 없으며, 점검확인서에서 점검 항목을 확인할 수 있습니다.'
        WHEN 134 THEN '기기 종류별 관리 시스템은 다음과 같습니다.\n\n- Android: Argos MDM 또는 Argos AMA\n- iPad: Argos MDM 및 Apple School Manager(ASM)\n- Windows: Argos MDM\n- Chromebook: Google 관리콘솔 및 CEU\n- Whale북: WBC(Whalebook Control)\n\nChromebook·Whale북은 별도 설치형 MDM 앱 대신 계정·클라우드 플랫폼 기반으로 관리합니다. 기기 도입 연도와 학교 설정에 따라 세부 구성이 다를 수 있습니다.'
        WHEN 135 THEN '신규 보급 또는 분실·재구매 기기는 자료상 관리 시스템이 설치·등록된 상태로 제공됩니다. 학교 관리자는 기기에서 필요한 권한 승인과 동기화를 완료한 뒤 관리 콘솔의 최근 연결·앱 설치 상태를 확인합니다. 실제 설정 상태는 해당 기기의 OS와 보급 조건에 따라 점검합니다.'
        WHEN 136 THEN '공장 초기화 후 관리 시스템 재설치 여부는 OS와 등록 상태에 따라 다릅니다.\n\n- Android·Windows: 관리 앱 재설치가 필요할 수 있습니다.\n- Chromebook·Whale북: 별도 MDM 앱 재설치 없이 플랫폼에 다시 연결합니다.\n- iPad: 기기의 일련번호가 ASM에 등록되어 있으면 인터넷 연결 후 관리 등록이 다시 적용될 수 있습니다.\n\n학교 정책과 실제 등록 상태를 확인한 뒤 필요한 절차를 진행합니다.'
        WHEN 137 THEN '잠금 비밀번호 초기화 가능 여부는 OS와 관리 시스템 기능에 따라 다릅니다. Android·iPad는 관리 콘솔의 간편 초기화 또는 비밀번호 초기화 기능을 사용할 수 있습니다. Windows는 정책상 MDM으로 초기화할 수 없는 경우 A/S를 접수합니다. Chromebook은 Google 관리콘솔의 기기 설정에서 빠른 잠금 해제·잠금 화면 PIN 정책을 확인합니다. 메뉴와 기능은 OS·관리 설정에 따라 다를 수 있습니다.'
        WHEN 138 THEN '초기화 명령이 대기 중이고 Wi-Fi 상태가 갱신되지 않으면 기기가 관리 서버와 실제로 연결되지 않았을 수 있습니다. 비밀번호 분실 후 재부팅한 경우 화면에 Wi-Fi 표시가 있더라도 네트워크 연결이 복구되지 않았을 수 있습니다. 기기가 학교 Wi-Fi 또는 인터넷에 연결되어 관리 서버와 통신하는지 확인합니다. 연결 후에도 명령이 반영되지 않으면 기술지원 또는 A/S를 요청합니다.'
        WHEN 139 THEN 'Argos MDM과 Argos AMA는 Android 기기 관리 방식이 다릅니다. Argos MDM은 Google Play 스토어 앱을 직접 배포하지 못해 설치 파일을 별도로 준비해 배포합니다. Argos AMA는 Google Play 스토어 연동 앱 배포를 지원하는 방식입니다. 실제 지원 기능은 기기 도입 연도와 학교 설정을 확인합니다.'
        WHEN 140 THEN '학교 관리 대상 기기에서 관리 앱이 보이지 않으면 기종과 등록 상태를 먼저 확인합니다. 학교 관리자가 승인된 설치 파일과 절차를 보유한 경우 해당 안내에 따라 설치할 수 있습니다. 설치 파일이 없거나 설치가 되지 않으면 관리 시스템 기술지원센터 또는 A/S 접수 경로를 이용합니다.'
        WHEN 141 THEN 'MDM·AMA 기술 지원은 MDM 기술지원센터(1666-6493)에 문의합니다. 문의 시 기기 OS·도입 연도, 관리 시스템 종류, 화면에 표시된 상태와 발생 시점을 함께 준비합니다.'
        WHEN 142 THEN '관리 명령·정책 설정 문의는 MDM 기술지원센터에 문의하고, 기기 자체의 고장이나 초기화가 필요한 증상은 A/S 접수 경로로 안내합니다. 두 지원처에서 서로 다른 경로를 안내한 경우 오류 화면과 이미 확인한 조치 내용을 함께 전달해 담당 범위를 확인합니다.'
        WHEN 143 THEN '관리 콘솔의 단말 현황에서 Wi-Fi 아이콘이 표시되지 않으면 해당 기기의 관리 앱 설치·등록 상태가 정상적으로 보고되지 않는지 확인합니다. 학교 관리 대상 기기에서 관리 앱이 설치되지 않은 것으로 확인되면 OS별 절차에 따라 재설치합니다. 판단이 어렵거나 재설치 후에도 표시되지 않으면 MDM 기술지원센터(1666-6493)에 문의합니다.'
        WHEN 144 THEN 'FCM 토큰 만료는 기기가 오랫동안 꺼져 있었거나 Argos MDM 앱이 실행되지 않아 서버 연결이 갱신되지 않은 경우 발생할 수 있습니다.\n\n1. 기기를 충전하고 전원을 켭니다.\n2. 학교 Wi-Fi에 연결합니다.\n3. Argos MDM 앱을 직접 실행합니다.\n4. 관리자 콘솔에서 최근 연결 시간이 갱신되고 상태가 정상으로 바뀌었는지 확인합니다.\n\n상태가 회복되지 않으면 MDM 기술지원센터(1666-6493)에 문의합니다.'
        WHEN 145 THEN '관리 콘솔의 단말 상세 화면에 표시되는 코드는 학생이 기기 자체에 설정한 잠금 비밀번호(PIN·패턴 등)가 아닙니다. 해당 코드로 개인 잠금 비밀번호를 확인할 수 없습니다. 비밀번호 분실 시 OS별 공식 초기화·관리 절차를 이용합니다.'
        WHEN 146 THEN '앱 배포 방식은 OS와 앱 제공처에 따라 다릅니다.\n\n- InHouse: 관리자가 APK·EXE 등 설치 파일을 등록해 배포합니다.\n- 스토어 연동: iPad는 App Store·VPP, Windows는 Microsoft Store 등 연동된 스토어의 앱을 배포할 수 있습니다.\n\n학교 관리 정책과 해당 OS에서 지원하는 배포 방식을 확인합니다.'
        WHEN 147 THEN 'MDM에서 앱을 배포하는 세부 절차는 MDM 기술지원센터(1666-6493)에 문의합니다. 앱 이름, 대상 OS·기기, 배포 방식과 관리 콘솔의 현재 상태를 함께 준비합니다.'
        WHEN 148 THEN 'Argos AMA에서 앱을 배포하는 세부 절차는 MDM 기술지원센터(1666-6493)에 문의합니다. 앱 이름, 대상 OS·기기, 배포 방식과 관리 콘솔의 현재 상태를 함께 준비합니다.'
        WHEN 149 THEN '분실 기기의 위치 확인은 학교의 권한 있는 정보화 기기 담당자가 관리 시스템에서 확인합니다. 자료상 Android·iPad·Windows는 위치 확인을 지원할 수 있고 Whale북은 지원하지 않습니다. Chromebook은 실시간 위치 추적 대신 Google 관리콘솔에서 기기 잠금과 마지막 접속 IP를 확인할 수 있습니다. 실제 기능은 OS·설정·네트워크 상태에 따라 달라집니다.'
        WHEN 150 THEN '위치 확인 기능이 지원되는 기기는 관리자가 콘솔에서 분실 등록 후 위치 정보를 확인합니다. 분실 등록 시점의 위치가 전송될 수 있으며, 이후 위치 갱신은 콘솔에서 별도로 요청해야 합니다. 지속적인 이동 경로 추적 기능으로 간주하지 않습니다. 기기의 전원이 꺼져 있거나 인터넷·위치 신호를 사용할 수 없으면 최신 위치를 받을 수 없습니다.'
        WHEN 151 THEN '분실 등록 명령은 기기가 켜져 있고 인터넷에 연결되어 관리 서버와 통신할 때 적용됩니다. 전원이 꺼져 있거나 Wi-Fi·LTE 연결이 끊겨 있으면 명령이 대기 상태로 남고, 기기가 다시 연결된 뒤 처리될 수 있습니다. 콘솔에서 대기 상태와 최근 연결 시간을 확인합니다.'
        WHEN 152 THEN '분실 등록 기기의 잠금 해제는 설정된 관리 방식에 따라 진행합니다.\n\n- Wi-Fi 신호 방식: 기기가 지정된 Wi-Fi에 연결되면 해제될 수 있습니다.\n- OTP 방식: 관리자 콘솔에서 발급한 OTP 정보를 잠긴 기기에 입력합니다.\n\n학교에서 설정한 절차와 관리 시스템 안내를 확인합니다.'
        WHEN 153 THEN '“IT 관리자에게 문의하세요” 메시지와 Wi-Fi 미연결 상태가 함께 표시되면 관리 정책 또는 네트워크 연결 문제일 수 있습니다. 기기가 학교 Wi-Fi에 연결되어 있는지 확인한 뒤 MDM 기술지원센터(1666-6493)에 문의합니다.'
        WHEN 154 THEN '전입·전출에 따른 학생 학적정보와 기기 매칭은 학교 담당자가 CEU 또는 해당 MDM에서 관리합니다. 메뉴 사용이나 변경 절차 문의는 MDM 기술지원센터(1666-6493)에, Chromebook 관리콘솔 문의는 DBS 화면의 최신 지원 안내에 따라 문의합니다.'
        WHEN 155 THEN 'AMA 등록용 QR 코드는 학교 내부망에서 MDM 관리 페이지에 접속해 조회합니다. Android(AMA) 메뉴에서 대상 단말을 선택하고 QR 코드 기능을 엽니다. QR 코드에는 유효기간이 있으므로 만료된 경우 화면의 새로고침 기능으로 다시 발급합니다. QR 코드는 기기 등록 목적에 한해 사용하고 외부에 공유하지 않습니다.'
        WHEN 156 THEN 'MDM 비밀번호 초기화 명령 후 여러 기기가 프로키오스크 모드로 전환되었거나 원래 화면으로 돌아오지 않으면 추가 명령이나 임의의 공통 비밀번호 입력을 반복하지 않습니다. 기기 종류, 발생 시간, 적용한 명령과 화면 상태를 정리해 MDM 기술지원센터(1666-6493)에 문의합니다.'
        ELSE content
    END
WHERE id BETWEEN 123 AND 156
  AND category_id = (SELECT id FROM faq_categories WHERE name = '유지보수');
